"""docich#4530: a chapterless bot on the field opens the interior menu with one
bounded A, then walks メインメニュー -> ステータス to read the castle name."""

from docich.hanjuku_speedrun.hanjuku.flows import deploy
from docich.hanjuku_speedrun.hanjuku.flows.prompts import observe_events
from docich.hanjuku_speedrun.hanjuku.os_layer.commands import pad
