from .test_hanjuku_chart_bot import MONTH_GRID, month_canvas


def _line(y, x, text):
    return TextLine(y, tuple((x + 8 * i, ch) for i, ch in enumerate(text)))


def _screen(kind, rows, *, hand=None, text='', cursor=None):
    lines = [_line(y, x, word) for y, x, word in rows]
    return Screen(lines=lines, hand=hand, text=text or ' '.join(w for _, _, w in rows),
                  kind=kind, cursor=cursor)


def field():
    """The free field map: a measured cursor, no menu text and no hand."""
    return Screen(lines=[], hand=None, text='', kind='map', cursor=(120, 100))


def interior_menu(on='しょうにん'):
    """The A-opened castle interior menu, which shares the monthly layout."""
    screen = parse(month_canvas(250, on=on))
    assert screen.kind == 'month_menu'
    return screen


def main_menu(hand_y=39):
    rows = [(39, 168, 'ステータス'), (55, 168, 'しょうぐん'), (71, 168, 'しろ'),
            (87, 168, 'きりふだ'), (103, 168, 'システム')]
    return _screen('main_menu', rows, hand=(146, hand_y - 6, 166, hand_y + 7),
                   text='ステータス しょうぐん しろ きりふだ システム')


def status_panel(name):
    """The メインメニュー ステータス panel: an info read, not the compact menu."""
    rows = [(31, 120, name + 'じょう'), (47, 120, 'ステータス'),
            (47, 168, 'しゅうにゅう'), (63, 120, 'しょうぐん')]
    return _screen('castle_info', rows,
                   text=name + 'じょうステータスしゅうにゅう しょうぐん')


def lost_chapter(**fields):
    """A running bot that resumed a battery save without a chapter."""
    mem = {'tick': 5, 'month': '8-3', 'resume_chapter_pending': True}
    mem.update(fields)
    return mem


def test_probe_owns_the_field_and_every_menu_on_the_route():
    assert deploy.CHAPTER_PROBE_KINDS == frozenset(
        {'map', 'month_menu', 'main_menu', 'castle_menu', 'castle_info'})


def test_chapterless_map_presses_one_bounded_a_then_holds():
    mem = lost_chapter()
    for _ in range(deploy.CHAPTER_PROBE_MAP_OPEN_LIMIT):
        assert deploy.chapterless_status_step(field(), mem) == [pad('a')]
    assert deploy.chapterless_status_step(field(), mem) == []
    assert mem['chapter_probe']['map_presses'] == deploy.CHAPTER_PROBE_MAP_OPEN_LIMIT


def test_map_presses_reset_with_the_month():
    mem = lost_chapter()
    for _ in range(deploy.CHAPTER_PROBE_MAP_OPEN_LIMIT):
        deploy.chapterless_status_step(field(), mem)
    mem['month'] = '8-4'
    assert deploy.chapterless_status_step(field(), mem) == [pad('a')]
    assert mem['chapter_probe']['map_presses'] == 1


def test_field_with_an_owner_is_not_probed():
    for owner in ({'plan': {'active': 'J1'}}, {'battle': {'seed': 1}},
                  {'month_sub': {'kind': 'recruit'}}, {'house': {'level_only': True}}):
        mem = lost_chapter(**owner)
        assert deploy.chapterless_status_step(field(), mem) == []
        assert 'map_presses' not in mem.get('chapter_probe', {})


def test_interior_menu_moves_down_to_the_main_menu_row():
    mem = lost_chapter()
    assert deploy.chapterless_status_step(interior_menu('しょうにん'), mem) == [pad('down')]
    assert deploy.chapterless_status_step(interior_menu('ちくじょう'), mem) == [pad('down')]
    assert 'main_opens' not in mem['chapter_probe']


def test_interior_menu_opens_the_main_menu_and_counts_the_open():
    mem = lost_chapter()
    assert deploy.chapterless_status_step(interior_menu('メインメニュー'), mem) == [pad('a')]
    assert mem['chapter_probe']['main_opens'] == 1


def test_main_menu_openings_are_bounded():
    mem = lost_chapter()
    for _ in range(deploy.CHAPTER_PROBE_MAIN_OPEN_LIMIT):
        assert deploy.chapterless_status_step(interior_menu('メインメニュー'), mem) == [pad('a')]
    assert deploy.chapterless_status_step(interior_menu('メインメニュー'), mem) == []


def test_confirmation_over_the_interior_menu_is_declined_never_confirmed():
    rows = [(y, x, w) for w, (x, y) in MONTH_GRID.items()]
    rows += [(167, 160, 'うむッ!'), (183, 160, 'いかんッ!')]
    screen = _screen('month_menu', rows, hand=(146, 161, 164, 174))
    mem = lost_chapter()
    assert deploy.chapterless_status_step(screen, mem) == [pad('b')]


def test_main_menu_moves_up_to_status_then_opens_the_panel():
    mem = lost_chapter()
    assert deploy.chapterless_status_step(main_menu(103), mem) == [pad('up')]
    assert deploy.chapterless_status_step(main_menu(39), mem) == [pad('a')]
    assert mem['chapter_probe']['opens'] == 1


def test_info_panel_without_a_resolvable_name_closes():
    screen = _screen('castle_info', [(31, 120, 'なにかのじょうほう')],
                     text='なにかのじょうほう')
    mem = lost_chapter()
    assert deploy.chapterless_status_step(screen, mem) == [pad('b')]


def test_the_full_route_fixes_the_chapter_from_the_status_panel():
    mem = lost_chapter()
    # field -> interior menu -> メインメニュー -> main menu -> ステータス -> panel
    assert deploy.chapterless_status_step(field(), mem) == [pad('a')]
    assert deploy.chapterless_status_step(interior_menu('メインメニュー'), mem) == [pad('a')]
    assert deploy.chapterless_status_step(main_menu(39), mem) == [pad('a')]
    observe_events(status_panel('あるまむーん'), mem)
    assert mem['chapter'] == 8 and 'resume_chapter_pending' not in mem
    # With the chapter known the probe retires and owns nothing.
    assert deploy.chapterless_status_step(main_menu(39), mem) is None
    assert 'chapter_probe' not in mem


def test_orchestrator_routes_the_chapterless_interior_menu_to_the_probe(monkeypatch):
    calls = []
    monkeypatch.setattr(deploy, 'chapterless_status_step',
                        lambda s, m: calls.append(s.kind) or [])
    decide(month_canvas(250), {'policy': {'resume_chapter_pending': True, 'tick': 5}})
    assert calls == ['month_menu']


def test_decide_opens_the_main_menu_from_a_real_interior_menu_frame():
    actions, state = decide(month_canvas(250, on='メインメニュー'),
                            {'policy': {'resume_chapter_pending': True, 'tick': 5}})
    assert actions == [pad('a')]
    assert state['policy']['chapter_probe']['main_opens'] == 1
